breach.segment:
// MySQL instances with at least 5 observed minutes in the window
WHERE marker > 0 AND observed_minutes >= 5
// Threshold: average at or above 90% of reserved CPU across the window
| WHERE avg_cpu >= 0.9
| EVAL avg_cpu_pct = ROUND(avg_cpu * 100, 1),
       peak_cpu_pct = ROUND(cpu_peak * 100, 1)
| SORT avg_cpu_pct DESC, database_id ASC
// Up to 1000 breaching instances per run (the ES|QL default row limit); raise it for larger fleets
| LIMIT 1000
| KEEP database_id, avg_cpu_pct, peak_cpu_pct, observed_minutes
